import {
  NEWLINE,
  RPC4NEXT_CLIENT_TEST_GENERATED_IMPORT_PATH,
  RPC4NEXT_GENERATED_SCHEMA_VERSION,
  RPC4NEXT_CLIENT_IMPORT_PATH,
  RPC4NEXT_SERVER_GENERATED_IMPORT_PATH,
  STATEMENT_TERMINATOR,
  TYPE_KEYS,
  TYPE_RPC_GENERATED_PATH_STRUCTURE,
} from "./constants.js";
import { createRelativeImportPath } from "./path-utils.js";
import { scanAppDir } from "./route-scanner.js";
import type { PageManifest, RouteManifest } from "./route-scanner.js";
import { createImport, createStringLiteral } from "./type-utils.js";

export const ROUTE_CONTRACT_GENERATED_MARKER =
  "// Generated by rpc4next-cli. Do not edit manually.";
const TEST_MANIFEST_BUNDLE_SENTINEL = "rpc4next-test-manifest-client-bundle-leak-sentinel";

type GeneratedParamsType = {
  dirPath: string;
  paramsType: string;
};

type GeneratedPathStructure = {
  paramsTypes: GeneratedParamsType[];
  pathStructure: string;
  pageManifests?: readonly PageManifest[];
  routeManifests?: readonly RouteManifest[];
};

type GenerateTestRouteManifestOptions = {
  includeBundleLeakSentinel?: boolean;
};

const isPageManifestArray = (
  value: readonly PageManifest[] | GenerateTestRouteManifestOptions,
): value is readonly PageManifest[] => Array.isArray(value);

export const generateTestManifest = (
  outputPath: string,
  routeManifests: readonly RouteManifest[],
  pageManifestsOrOptions: readonly PageManifest[] | GenerateTestRouteManifestOptions = [],
  options: GenerateTestRouteManifestOptions = {},
) => {
  const hasPageManifests = isPageManifestArray(pageManifestsOrOptions);
  const pageManifests = hasPageManifests ? pageManifestsOrOptions : [];
  const resolvedOptions = hasPageManifests ? options : pageManifestsOrOptions;
  const routes = routeManifests.map(({ fullPath, methods, pathname }) => {
    const importPath = createRelativeImportPath(outputPath, fullPath);
    const methodList = `[${methods.map((method) => createStringLiteral(method)).join(", ")}]`;

    return [
      "  {",
      `    pathname: ${createStringLiteral(pathname)},`,
      `    methods: ${methodList},`,
      `    load: () => import(${createStringLiteral(importPath)}) as unknown as Promise<RpcTestRouteModule>,`,
      "  },",
    ].join(NEWLINE);
  });
  const pages = pageManifests.map(({ fullPath, pathname }) => {
    const importPath = createRelativeImportPath(outputPath, fullPath);

    return [
      "  {",
      `    pathname: ${createStringLiteral(pathname)},`,
      `    load: () => import(${createStringLiteral(importPath)}) as unknown as Promise<RpcTestPageModule>,`,
      "  },",
    ].join(NEWLINE);
  });
  const bundleLeakSentinel = resolvedOptions.includeBundleLeakSentinel
    ? [
        `const testManifestBundleSentinel = ${createStringLiteral(TEST_MANIFEST_BUNDLE_SENTINEL)};`,
        "(globalThis as unknown as Record<string, string>).__rpc4nextTestRouteManifestBundleSentinel =",
        "  testManifestBundleSentinel;",
        "",
      ]
    : [];

  return [
    ROUTE_CONTRACT_GENERATED_MARKER,
    "",
    'import "rpc4next/server-only";',
    createImport(
      "RpcTestPage, RpcTestPageModule, RpcTestRoute, RpcTestRouteModule",
      RPC4NEXT_CLIENT_TEST_GENERATED_IMPORT_PATH,
    ),
    "",
    ...bundleLeakSentinel,
    "export const testRoutes = [",
    routes.join(NEWLINE),
    "] as const satisfies readonly RpcTestRoute[];",
    "",
    "export const testPages = [",
    pages.join(NEWLINE),
    "] as const satisfies readonly RpcTestPage[];",
  ].join(NEWLINE);
};

export const generatePathStructure = (
  outputPath: string,
  baseDir: string,
): GeneratedPathStructure => {
  const {
    pathStructure,
    imports,
    pageManifests = [],
    paramsTypes,
    routeManifests = [],
  } = scanAppDir(outputPath, baseDir);
  const pathStructureType = `export type PathStructure = ${TYPE_RPC_GENERATED_PATH_STRUCTURE}<${pathStructure || "{}"}, ${RPC4NEXT_GENERATED_SCHEMA_VERSION}>${STATEMENT_TERMINATOR}`;

  const importsStr = imports.length
    ? `${imports
        .sort((a, b) => a.path.localeCompare(b.path, undefined, { numeric: true }))
        .map((v) => v.statement)
        .join(NEWLINE)}`
    : "";

  const keyTypes = [
    TYPE_RPC_GENERATED_PATH_STRUCTURE,
    ...TYPE_KEYS.filter((type) => pathStructure.includes(type)),
  ];
  const keyTypesImportStr = createImport(keyTypes.join(" ,"), RPC4NEXT_CLIENT_IMPORT_PATH);
  const dirParamsTypes = paramsTypes.map(({ paramsType, dirPath, pathname }) => {
    const params = [
      ROUTE_CONTRACT_GENERATED_MARKER,
      "",
      createImport("ProcedureRouteContract", RPC4NEXT_SERVER_GENERATED_IMPORT_PATH),
      "",
      `export type Params = ${paramsType}${STATEMENT_TERMINATOR}`,
      `export type RouteContract = ProcedureRouteContract<${createStringLiteral(pathname)}, Params>${STATEMENT_TERMINATOR}`,
      "",
      "export const routeContract = {",
      `  pathname: ${createStringLiteral(pathname)},`,
      "  params: {} as Params,",
      "} as RouteContract;",
    ].join(NEWLINE);

    return {
      paramsType: params,
      dirPath,
    };
  });

  return {
    pathStructure: [
      ROUTE_CONTRACT_GENERATED_MARKER,
      "",
      keyTypesImportStr,
      importsStr,
      "",
      pathStructureType,
    ].join(NEWLINE),
    pageManifests,
    paramsTypes: dirParamsTypes,
    routeManifests,
  };
};
